/// Foreign-trait callback for download progress events from
/// [`BundleRepo::with_progress`]. Implementers (Kotlin class, Swift
/// class, Python subclass) drive a progress UI from these events.
///
/// All methods are required from foreign implementations (UniFFI
/// 0.31 foreign traits don't carry Rust default-impl fallbacks).
///
/// Threading: `on_progress` is invoked from the thread driving the
/// download. For sync `from_bundle_id` that's the caller's thread;
/// for `from_bundle_id_async` it's a tokio blocking worker. If your
/// progress UI requires marshalling onto a UI thread (`@MainActor`,
/// `runOnUiThread`, etc.), the implementer is responsible for the
/// dispatch.
abstract interface class DownloadProgressSink {
  /// Called periodically during a download. `bytes_downloaded` is
  /// monotonic across the same call's stream; `total_bytes` is the
  /// `Content-Length` reported by the server (may be `None` for
  /// chunked-transfer responses or when HEAD didn't surface a
  /// length). Same `url` value across all calls for one download
  /// — pattern-match on it to drive a per-file UI within a
  /// multi-file bundle download.
  ///
  /// Throttled by `cera-core` to ~256 KB granularity + one final
  /// callback at end-of-stream so the consumer always sees the
  /// final byte count.
  void onProgress(String url, int bytesDownloaded, int? totalBytes);
}

final class _DownloadProgressSinkFinalizerToken {
  const _DownloadProgressSinkFinalizerToken(this.free, this.handle);
  final void Function(int) free;
  final int handle;
}

final class _DownloadProgressSinkImpl implements DownloadProgressSink {
  _DownloadProgressSinkImpl._(this._ffi, this._handle) {
    _finalizer.attach(this, _DownloadProgressSinkFinalizerToken(_ffi._downloadProgressSinkFree, _handle), detach: this);
  }

  final CeraFfiFfi _ffi;
  int _handle;
  bool _closed = false;

  static final Finalizer<_DownloadProgressSinkFinalizerToken> _finalizer = Finalizer((token) {
    token.free(token.handle);
  });

  bool get isClosed => _closed;

  void close() {
    if (_closed) {
      return;
    }
    _closed = true;
    _finalizer.detach(this);
    _ffi._downloadProgressSinkFree(_handle);
  }

  void _ensureOpen() {
    if (_closed) {
      throw StateError('_DownloadProgressSinkImpl is closed');
    }
  }

  /// Called periodically during a download. `bytes_downloaded` is
  /// monotonic across the same call's stream; `total_bytes` is the
  /// `Content-Length` reported by the server (may be `None` for
  /// chunked-transfer responses or when HEAD didn't surface a
  /// length). Same `url` value across all calls for one download
  /// — pattern-match on it to drive a per-file UI within a
  /// multi-file bundle download.
  ///
  /// Throttled by `cera-core` to ~256 KB granularity + one final
  /// callback at end-of-stream so the consumer always sees the
  /// final byte count.
  @override
  void onProgress(String url, int bytesDownloaded, int? totalBytes) {
    _ensureOpen();
    _ffi.downloadProgressSinkInvokeOnProgress(_handle, url, bytesDownloaded, totalBytes);
  }

}

final class _DownloadProgressSinkTraitVTable extends ffi.Struct {
  external ffi.Pointer<ffi.NativeFunction<ffi.Void Function(ffi.Uint64 handle)>> uniffiFree;

  external ffi.Pointer<ffi.NativeFunction<ffi.Uint64 Function(ffi.Uint64 handle)>> uniffiClone;

  external ffi.Pointer<ffi.NativeFunction<ffi.Void Function(ffi.Uint64 handle, _UniFfiRustBuffer url, ffi.Uint64 bytesDownloaded, _UniFfiRustBuffer totalBytes, ffi.Pointer<ffi.Void> outReturn, ffi.Pointer<_UniFfiRustCallStatus> outStatus)>> onProgress;

}

final class _DownloadProgressSinkTraitCallbackBridge {
  _DownloadProgressSinkTraitCallbackBridge._();
  static final _DownloadProgressSinkTraitCallbackBridge instance = _DownloadProgressSinkTraitCallbackBridge._();

  final Map<int, DownloadProgressSink> _callbacks = <int, DownloadProgressSink>{};
